import React from 'react';
import { BrowserRouter, Routes, Route, NavLink } from 'react-router-dom';
import Dashboard from './pages/Dashboard';
import Events from './pages/Events';
import Predict from './pages/Predict';
import Report from './pages/Report';

const NAV = [
  { to: '/',        label: '📊 Dashboard' },
  { to: '/events',  label: '🔍 Live Events' },
  { to: '/predict', label: '🤖 Predict' },
  { to: '/report',  label: '📋 Handover Report' },
];

export default function App() {
  return (
    <BrowserRouter>
      <div className="min-h-screen flex flex-col">
        {/* Header */}
        <header className="bg-blue-900 text-white shadow-lg">
          <div className="max-w-7xl mx-auto px-4 py-3 flex items-center justify-between">
            <div>
              <h1 className="text-xl font-bold tracking-tight">🛡️ XAI Admin Monitor</h1>
              <p className="text-blue-300 text-xs">Explainable AI — Website Security Dashboard</p>
            </div>
            <nav className="flex gap-1">
              {NAV.map(({ to, label }) => (
                <NavLink
                  key={to}
                  to={to}
                  end={to === '/'}
                  className={({ isActive }) =>
                    `px-3 py-1.5 rounded text-sm font-medium transition-colors ${
                      isActive ? 'bg-white text-blue-900' : 'text-blue-200 hover:bg-blue-800'
                    }`
                  }
                >
                  {label}
                </NavLink>
              ))}
            </nav>
          </div>
        </header>

        {/* Page content */}
        <main className="flex-1 max-w-7xl w-full mx-auto px-4 py-6">
          <Routes>
            <Route path="/"        element={<Dashboard />} />
            <Route path="/events"  element={<Events />} />
            <Route path="/predict" element={<Predict />} />
            <Route path="/report"  element={<Report />} />
          </Routes>
        </main>

        <footer className="bg-white border-t text-center text-xs text-gray-400 py-3">
          XAI Admin Monitor · Abubakar Dahiru · KASU Final Year Project
        </footer>
      </div>
    </BrowserRouter>
  );
}
